def categorize_bank():
    with app.app_context():
        print("Scanning MasterQuestion bank for categorization...")
        questions = MasterQuestion.query.all()
        updated_count = 0

        for q in questions:
            # Only categorize if it's currently 'General GK' or empty
            if q.sub_topic in ["General GK", "General", None]:
                found_topic = None
                
                # Check keywords
                for topic, keywords in TOPIC_MAPPING.items():
                    for kw in keywords:
                        if kw in q.text:
                            found_topic = topic
                            break
                    if found_topic:
                        break
                
                if found_topic:
                    q.sub_topic = found_topic
                    updated_count += 1

        db.session.commit()
        print(f"Successfully categorized {updated_count} questions into specific sub-topics!")

def clean_duplicates():
    """Optional: Remove exact duplicate text entries if the scraper ran twice."""
    with app.app_context():
        all_q = MasterQuestion.query.all()
        seen_text = set()
        dupes_removed = 0
        for q in all_q:
            if q.text in seen_text:
                db.session.delete(q)
                dupes_removed += 1
            else:
                seen_text.add(q.text)
        db.session.commit()
        if dupes_removed > 0:
            print(f"Removed {dupes_removed} duplicate questions.")

if __name__ == "__main__":
    categorize_bank()
    clean_duplicates()